"""Self-contained read-only dashboard, styled consistently with axispy's camera desk."""
HTML = r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Root RTSP Bridge · Stream desk</title>
<style>
:root{color-scheme:dark;--bg:#0b1019;--card:#141d2b;--line:#29364a;--text:#edf3fa;--muted:#96a8bf;--accent:#5de3c4}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:15px system-ui,sans-serif}main{width:100%;margin:auto;padding:32px 28px}header,.section-heading,.top,.footer{display:flex;justify-content:space-between;align-items:center;gap:18px}h1{font-size:25px;letter-spacing:-1px;margin:0}h1 span{color:var(--accent)}.eyebrow{font-size:11px;text-transform:uppercase;letter-spacing:2px;color:var(--muted);margin:8px 0 0}.muted,.note,.footer{color:var(--muted)}.note{font-size:12px;line-height:1.6}.badge{display:inline-flex;align-items:center;gap:8px;font-size:12px;padding:7px 10px;border:1px solid var(--line);border-radius:7px;color:var(--muted);white-space:nowrap}.dot{width:8px;height:8px;border-radius:50%;background:#8799b0}.online{color:var(--accent)}.online .dot{background:var(--accent)}.offline{color:#ffb4b8}.offline .dot{background:#ff868b}.summary{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px;margin:28px 0 32px}.metric,.session,.panel{background:var(--card);border:1px solid var(--line);border-radius:12px;min-width:0}.metric{padding:18px 22px}.metric span{font-size:12px;color:var(--muted)}.metric strong{display:block;font-size:26px;font-weight:600;margin-top:8px;font-variant-numeric:tabular-nums}.metric:last-child strong{font-size:20px;line-height:1.6}.section-heading{margin:28px 0 14px}.section-heading h2{font-size:18px;margin:0}.section-heading p{margin:4px 0 0}.table-scroll{overflow-x:auto}table{width:100%;border-collapse:collapse;text-align:left;font-size:13px}th{font-size:11px;letter-spacing:.7px;text-transform:uppercase;color:var(--muted);font-weight:500;white-space:nowrap;background:#111a27}td,th{padding:16px 18px;border-bottom:1px solid var(--line);vertical-align:top}tbody tr:last-child td{border-bottom:0}.address{font:12px/1.6 ui-monospace,monospace;overflow-wrap:anywhere;min-width:200px;max-width:580px}.key{display:inline-block;background:#233246;border:1px solid #3d5069;padding:4px 8px;border-radius:6px;font:bold 12px ui-monospace,monospace}.pill{display:inline-block;padding:3px 7px;border:1px solid var(--line);border-radius:5px;color:var(--muted);font-size:11px;text-transform:uppercase}.count{font-size:17px;font-weight:600;color:var(--accent)}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,420px),1fr));gap:16px}.session{padding:20px}.session h3{font-size:19px;margin:20px 0 6px;font-family:ui-monospace,monospace;overflow-wrap:anywhere}.session-id{font:11px ui-monospace,monospace;color:var(--muted)}.facts{display:grid;grid-template-columns:1fr 1fr;gap:18px;margin:20px 0}.facts dt{font-size:12px;color:var(--muted);margin-bottom:6px}.facts dd{margin:0;font-size:15px;overflow-wrap:anywhere;font-variant-numeric:tabular-nums}details{border-top:1px solid var(--line);padding-top:14px}summary{cursor:pointer;color:var(--muted);font-size:12px}summary:hover,summary:focus-visible{color:var(--accent)}.detail-row{padding:12px 0;border-bottom:1px solid var(--line);font-size:12px;line-height:1.7;overflow-wrap:anywhere}.detail-row:last-child{border-bottom:0}.detail-row strong{color:var(--accent);font-weight:500}.empty{padding:36px;text-align:center;color:var(--muted);border:1px dashed var(--line);border-radius:12px;grid-column:1/-1}.empty strong{display:block;color:var(--text);font-size:16px;margin-bottom:8px}.footer{font-size:12px;margin-top:24px}.alert{color:#ffb4b8;font-size:13px;margin:16px 0}.alert:empty{display:none}@media(min-width:1800px){.grid{grid-template-columns:repeat(3,minmax(0,1fr))}}@media(max-width:800px){main{padding:24px 16px}.summary{grid-template-columns:repeat(2,minmax(0,1fr))}.section-heading,.footer{align-items:flex-start;flex-direction:column;gap:8px}}@media(max-width:450px){header{align-items:flex-start;flex-direction:column}.metric{padding:14px}.metric strong{font-size:23px}.metric:last-child strong{font-size:16px}td,th{padding:12px}.session{padding:16px}}
</style></head><body><main>
<header><div><h1>Root <span>RTSP</span> Bridge</h1><p class="eyebrow">Stream monitoring desk</p></div><div id="connection" class="badge"><span class="dot"></span><span id="connectionText">Connecting…</span></div></header>
<section class="summary" aria-label="Bridge summary"><div class="metric"><span>Configured routes</span><strong id="routeCount">—</strong></div><div class="metric"><span>Connected sessions</span><strong id="connected">—</strong></div><div class="metric"><span>Playing sessions</span><strong id="playing">—</strong></div><div class="metric"><span>Bridge uptime</span><strong id="uptime">—</strong></div></section>
<div id="alert" class="alert" role="status"></div>
<section aria-labelledby="routesHeading"><div class="section-heading"><div><h2 id="routesHeading">Configured routes</h2><p class="note">Listening ports and upstream camera settings</p></div><span class="note">TLS verification applies to RTSPS · Credentials hidden</span></div><div class="panel table-scroll" id="routes" tabindex="0" role="region" aria-label="Configured route settings"><p class="empty">Loading routes…</p></div></section>
<section aria-labelledby="sessionsHeading"><div class="section-heading"><div><h2 id="sessionsHeading">Connected sessions</h2><p class="note">Live client connections and media activity</p></div><span class="note">Counters include RTP + RTCP · Camera → client / client → camera</span></div><div id="sessions" class="grid"><div class="empty">Waiting for session data…</div></div></section>
<footer class="footer"><span>Read-only monitor · Refreshes every 2 seconds</span><span id="updated">Awaiting first update</span></footer>
</main><script>
const $=id=>document.getElementById(id);
function node(tag,cls,text){const n=document.createElement(tag);if(cls)n.className=cls;if(text!==undefined)n.textContent=text;return n}
function badge(text,active){const b=node('span','badge'+(active?' online':''));b.append(node('span','dot'),document.createTextNode(text));return b}
function renderRoutes(routes){const table=node('table'),head=node('thead'),row=node('tr');for(const title of ['Port','Connections','Upstream URL','TLS verify','Credentials','Client transport','Camera transport','Audio']){const th=node('th','',title);th.scope='col';row.append(th)}head.append(row);table.append(head);const body=node('tbody');for(const r of routes){const tr=node('tr');for(const v of [node('span','key',r.listen_port),node('span','count',r.connected),node('div','address',r.upstream_url),String(r.tls_verify),node('span','pill',r.credential_mode),node('span','pill',r.downstream_transport),node('span','pill',r.upstream_transport),r.audio_enabled?'Enabled':'Disabled']){const td=node('td');td.append(typeof v==='string'?document.createTextNode(v):v);tr.append(td)}body.append(tr)}table.append(body);$('routes').replaceChildren(table)}
function bytes(n){if(n<1024)return n+' B';const units=['KiB','MiB','GiB','TiB'];let i=-1;do{n/=1024;i++}while(n>=1024&&i<units.length-1);return n.toFixed(1)+' '+units[i]}
function fact(list,label,value){const box=node('div');box.append(node('dt','',label),node('dd','',value));list.append(box)}
function renderSessions(sessions){const grid=$('sessions'),open=new Set([...grid.querySelectorAll('details[open]')].map(d=>d.dataset.session));const cards=sessions.map(s=>{const card=node('article','session'),top=node('div','top');top.append(node('span','key','Port '+s.route_port),badge(s.state,s.state==='playing'));card.append(top,node('h3','',s.source_ip),node('div','session-id','Session '+s.id));const facts=node('dl','facts');fact(facts,'Connected for',s.age);const video=(s.sdp||[]).filter(t=>t.media==='video');fact(facts,'Video resolution',video.map(t=>t.resolution?t.resolution.width+' × '+t.resolution.height:'Unavailable').join(', ')||'Unavailable');fact(facts,'Packets → / ←',s.packets.map(n=>n.toLocaleString()).join(' / '));fact(facts,'Media → / ←',s.bytes.map(bytes).join(' / '));card.append(facts);const details=node('details');details.dataset.session=s.id;details.open=open.has(s.id);details.append(node('summary','','Track counters & SDP details'));for(const t of s.tracks){const line=node('div','detail-row');line.append(node('strong','','Transport track '+t.index),node('div','muted','Packets → / ←: '+t.packets.join(' / ')),node('div','muted','Bytes → / ←: '+t.bytes.join(' / ')));details.append(line)}if(s.sdp===null)details.append(node('div','detail-row muted','SDP unavailable · Waiting for DESCRIBE'));else if(!s.sdp.length)details.append(node('div','detail-row muted','No advertised SDP media tracks'));else s.sdp.forEach((t,i)=>{const line=node('div','detail-row');line.append(node('strong','','SDP track '+i+' · '+t.media));for(const c of t.codecs)line.append(node('div','muted',c.codec+' · Payload '+c.payload_type+' · '+c.clock_rate+' Hz'+(c.channels?' · '+c.channels+' channel(s)':'')));if(!t.codecs.length)line.append(node('div','muted','Codec details unavailable'));details.append(line)});card.append(details);return card});if(!cards.length){const empty=node('div','empty');empty.append(node('strong','','No connected sessions'),'Sessions will appear when clients request a stream.');cards.push(empty)}grid.replaceChildren(...cards)}
async function refresh(){try{const response=await fetch('/api/status',{cache:'no-store'});if(!response.ok)throw Error();const s=await response.json();$('routeCount').textContent=s.routes.length;$('connected').textContent=s.connected;$('playing').textContent=s.playing;$('uptime').textContent=s.uptime;renderRoutes(s.routes);renderSessions(s.sessions);$('connection').className='badge online';$('connectionText').textContent='Bridge connected';$('updated').textContent='Updated '+new Date().toLocaleTimeString();$('alert').textContent=''}catch{$('connection').className='badge offline';$('connectionText').textContent='Connection lost';$('alert').textContent='Dashboard unavailable. Displayed values may be stale. Retrying…'}finally{setTimeout(refresh,2000)}}refresh();
</script></body></html>'''
